//Outputs the natively demangled Swift symbol found at the current address in expanded tree form.
//Mostly useful for debugging.
//@category Demangler
using ghidra.app.script;
using ghidra.app.util.demangler;
using ghidra.app.util.demangler;
using ghidra.app.util.demangler.swift;
using ghidra.app.util.demangler.swift.SwiftNativeDemangler;
using ghidra.program.model.symbol;

public class SwiftDemanglerScript : GhidraScript {

	/* @Override */
	protected void run()
    {
		SwiftDemangler demangler = new SwiftDemangler(currentProgram);
		SwiftDemanglerOptions options = new SwiftDemanglerOptions();
		if (!demangler.canDemangle(currentProgram)) {
			println("Not a Swift program");
			return;
		}
		println("-------------------------------------------------");

		string mangled = null;
		SymbolTable symbolTable = currentProgram.getSymbolTable();
		foreach (Symbol symbol in symbolTable.getSymbols(currentAddress)) {
			if (demangler.isSwiftMangledSymbol(symbol.getName())) {
				mangled = symbol.getName();
				break;
			}
			foreach (LabelHistory history in symbolTable.getLabelHistory(currentAddress)) {
				if (demangler.isSwiftMangledSymbol(history.getLabelString())) {
					mangled = history.getLabelString();
					break;
				}
			}
		}
		if (mangled == null) {
			println("No mangled Swift symbols found at " + currentAddress);
			return;
		}

		SwiftNativeDemangler nativeDemangler = new SwiftNativeDemangler();
		SwiftNativeDemangledOutput demangledOutput = nativeDemangler.demangle(mangled);
		println(demangledOutput.toString());

		MangledContext mangledContext =
			demangler.createMangledContext(mangled, options, currentProgram, currentAddress);
		DemangledObject demangledObject = demangler.demangle(mangledContext);
		if (demangledObject != null) {
			println(demangledObject.GetType().getSimpleName() + " " + mangled + " --> " +
				demangledObject);
		}
		else {
			println("Failed to demangle: " + mangled);
		}
	}
}
